import assert from "node:assert/strict";
import {resolve} from "node:path";
import {pathToFileURL} from "node:url";
const {randomScrambleForEvent} = await import(pathToFileURL(resolve("src/cubing/scramble/index.ts")));
const {Alg} = await import(pathToFileURL(resolve("src/cubing/alg/index.ts")));
const alg = await randomScrambleForEvent("444");
const text = alg.toString();
assert(text.trim().length > 0);
assert.equal(Alg.fromString(text).toString(), text);
console.log(JSON.stringify({event: "444", algorithm: text, leafMoves: [...alg.experimentalLeafMoves()].length}));
